update public.challenges set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{example,pt}',to_jsonb($q$Ele me pediu para fazer o trabalho dele; eu mandei ele ir pastar.$q$::text)),'{example,mark}',to_jsonb($q$va te faire voir$q$::text)),'{secondExample,pt}',to_jsonb($q$"Vão pastar com esses conselhos de vocês!", gritou o vizinho.$q$::text)),'{secondExample,mark}',to_jsonb($q$Allez vous faire voir$q$::text)),'{literal}',jsonb_build_object('pt',$q$vai se fazer ver$q$::text)) where id = 'expr-lote4-012' and data->'example'->>'text' = $q$Il m'a demandé de faire son travail à sa place ; je lui ai dit « va te faire voir ».$q$ and data->'secondExample'->>'text' = $q$« Allez vous faire voir avec vos conseils ! » a crié le voisin.$q$;
update public.challenges set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{example,pt}',to_jsonb($q$Desde que a gente recusou ir ao restaurante, o Julien está de cara fechada.$q$::text)),'{example,mark}',to_jsonb($q$tire la gueule$q$::text)),'{secondExample,pt}',to_jsonb($q$Ela ficou de cara fechada a noite toda porque tinham esquecido de convidá-la.$q$::text)),'{secondExample,mark}',to_jsonb($q$a tiré la gueule$q$::text)),'{literal}',jsonb_build_object('pt',$q$puxar o focinho$q$::text)) where id = 'expr-lote4-013' and data->'example'->>'text' = $q$Depuis qu'on a refusé d'aller au resto, Julien tire la gueule.$q$ and data->'secondExample'->>'text' = $q$Elle a tiré la gueule toute la soirée parce qu'on avait oublié de l'inviter.$q$;
update public.challenges set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{example,pt}',to_jsonb($q$Você viu o preço desse sanduíche? Estão de sacanagem com a gente!$q$::text)),'{example,mark}',to_jsonb($q$se foutent de notre gueule$q$::text)),'{secondExample,pt}',to_jsonb($q$Pare de tirar sarro da minha cara, sei que você está mentindo.$q$::text)),'{secondExample,mark}',to_jsonb($q$te foutre de ma gueule$q$::text)) where id = 'expr-lote4-014' and data->'example'->>'text' = $q$Tu as vu le prix de ce sandwich ? Ils se foutent de notre gueule !$q$ and data->'secondExample'->>'text' = $q$Arrête de te foutre de ma gueule, je sais que tu mens.$q$;
update public.challenges set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{example,pt}',to_jsonb($q$Com as provas chegando, todo mundo está com os nervos à flor da pele.$q$::text)),'{example,mark}',to_jsonb($q$est sur les nerfs$q$::text)),'{secondExample,pt}',to_jsonb($q$Não fale da conta com ele agora, ele já está com os nervos à flor da pele.$q$::text)),'{secondExample,mark}',to_jsonb($q$est déjà sur les nerfs$q$::text)),'{literal}',jsonb_build_object('pt',$q$estar sobre os nervos$q$::text)) where id = 'expr-lote4-015' and data->'example'->>'text' = $q$Avec les examens qui approchent, tout le monde est sur les nerfs.$q$ and data->'secondExample'->>'text' = $q$Ne lui parle pas de la facture maintenant, il est déjà sur les nerfs.$q$;
update public.challenges set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{example,pt}',to_jsonb($q$Leva um guarda-chuva, está chovendo canivete lá fora!$q$::text)),'{example,mark}',to_jsonb($q$il pleut des cordes$q$::text)),'{secondExample,pt}',to_jsonb($q$Ontem estava chovendo canivete e o jogo foi cancelado.$q$::text)),'{secondExample,mark}',to_jsonb($q$il pleuvait des cordes$q$::text)),'{literal}',jsonb_build_object('pt',$q$chove cordas$q$::text)) where id = 'expr-lote4-016' and data->'example'->>'text' = $q$Prends un parapluie, il pleut des cordes dehors !$q$ and data->'secondExample'->>'text' = $q$Hier, il pleuvait des cordes et le match a été annulé.$q$;
update public.challenges set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{example,pt}',to_jsonb($q$Para o casamento da filha, ele caprichou: orquestra, fogos de artifício, tudo.$q$::text)),'{example,mark}',to_jsonb($q$a mis le paquet$q$::text)),'{secondExample,pt}',to_jsonb($q$Se a gente quer ganhar a final, vai ter que dar o sangue.$q$::text)),'{secondExample,mark}',to_jsonb($q$mettre le paquet$q$::text)),'{literal}',jsonb_build_object('pt',$q$pôr o pacote$q$::text)) where id = 'expr-lote4-017' and data->'example'->>'text' = $q$Pour le mariage de sa fille, il a mis le paquet : orchestre, feu d'artifice, tout.$q$ and data->'secondExample'->>'text' = $q$Si on veut gagner la finale, il va falloir mettre le paquet.$q$;
update public.challenges set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{example,pt}',to_jsonb($q$Uma moto passou a mil na frente da escola.$q$::text)),'{example,mark}',to_jsonb($q$à fond la caisse$q$::text)),'{secondExample,pt}',to_jsonb($q$A gente estava atrasado, então atravessou a cidade a toda velocidade.$q$::text)),'{secondExample,mark}',to_jsonb($q$à fond la caisse$q$::text)),'{literal}',jsonb_build_object('pt',$q$a fundo a caixa (gíria: o carro)$q$::text)) where id = 'expr-lote4-018' and data->'example'->>'text' = $q$Une moto est passée à fond la caisse devant l'école.$q$ and data->'secondExample'->>'text' = $q$On était en retard, alors on a traversé la ville à fond la caisse.$q$;
update public.challenges set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{example,pt}',to_jsonb($q$O filme dá para assistir, mas não é nada de especial.$q$::text)),'{example,mark}',to_jsonb($q$ça ne casse pas des briques$q$::text)),'{secondExample,pt}',to_jsonb($q$O novo álbum dele não era nada de especial, as críticas foram mornas.$q$::text)),'{secondExample,mark}',to_jsonb($q$ne cassait pas des briques$q$::text)),'{literal}',jsonb_build_object('pt',$q$isso não quebra tijolos$q$::text)) where id = 'expr-lote4-019' and data->'example'->>'text' = $q$Le film se laisse regarder, mais ça ne casse pas des briques.$q$ and data->'secondExample'->>'text' = $q$Son nouvel album ne cassait pas des briques, les critiques étaient tièdes.$q$;
update public.challenges set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(data,'{example,pt}',to_jsonb($q$Você quer nadar no mar em janeiro? Você é doido!$q$::text)),'{example,mark}',to_jsonb($q$es cinglé$q$::text)),'{secondExample,pt}',to_jsonb($q$Meu vizinho é meio pirado: ele fala com as plantas o dia inteiro.$q$::text)),'{secondExample,mark}',to_jsonb($q$est un peu cinglé$q$::text)),'{literal}',jsonb_build_object('pt',$q$ser chicoteado$q$::text)) where id = 'expr-lote4-020' and data->'example'->>'text' = $q$Tu veux te baigner dans la mer en janvier ? Tu es cinglé !$q$ and data->'secondExample'->>'text' = $q$Mon voisin est un peu cinglé : il parle à ses plantes toute la journée.$q$;
-- tirer la gueule: aviso de registro dentro do texto do significado (autorizado em 2026-10-28)
update public.challenges set data = jsonb_set(data,'{meaning,pt}',to_jsonb(replace(data->'meaning'->>'pt','Registro: vulgar — pode ofender. Evite em contextos formais ou com desconhecidos.','Registro: familiar — use com amigos e pessoas próximas, evite em contextos formais.'))) where id='expr-lote4-013' and data->'meaning'->>'pt' like '%Registro: vulgar%';
